    external fun uniffi_lexicon_ffi_checksum_method_lexiconcontext_list_models(
    ): Short
    external fun uniffi_lexicon_ffi_checksum_method_modeldownloader_cancel_download(
    ): Short
    external fun uniffi_lexicon_ffi_checksum_method_modeldownloader_download_model(
    ): Short
