sealed class LexiconFfiException(message: String): kotlin.Exception(message) {
        
        class InitializationFailed(message: String) : LexiconFfiException(message)
        
        class ConfigException(message: String) : LexiconFfiException(message)
        
        class ModelNotFound(message: String) : LexiconFfiException(message)
        
        class ModelLoadFailed(message: String) : LexiconFfiException(message)
        
        class TranscriptionFailed(message: String) : LexiconFfiException(message)
        
        class SynthesisFailed(message: String) : LexiconFfiException(message)
        
        class InvalidInput(message: String) : LexiconFfiException(message)
        
        class IoException(message: String) : LexiconFfiException(message)
        
        class DatabaseException(message: String) : LexiconFfiException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LexiconFfiException> {
        override fun lift(error_buf: RustBuffer.ByValue): LexiconFfiException = FfiConverterTypeLexiconFfiError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeLexiconFfiError : FfiConverterRustBuffer<LexiconFfiException> {
    override fun read(buf: ByteBuffer): LexiconFfiException {
        
            return when(buf.getInt()) {
            1 -> LexiconFfiException.InitializationFailed(FfiConverterString.read(buf))
            2 -> LexiconFfiException.ConfigException(FfiConverterString.read(buf))
            3 -> LexiconFfiException.ModelNotFound(FfiConverterString.read(buf))
            4 -> LexiconFfiException.ModelLoadFailed(FfiConverterString.read(buf))
            5 -> LexiconFfiException.TranscriptionFailed(FfiConverterString.read(buf))
            6 -> LexiconFfiException.SynthesisFailed(FfiConverterString.read(buf))
            7 -> LexiconFfiException.InvalidInput(FfiConverterString.read(buf))
            8 -> LexiconFfiException.IoException(FfiConverterString.read(buf))
            9 -> LexiconFfiException.DatabaseException(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: LexiconFfiException): ULong {
        return 4UL
    }

    override fun write(value: LexiconFfiException, buf: ByteBuffer) {
        when(value) {
            is LexiconFfiException.InitializationFailed -> {
                buf.putInt(1)
                Unit
            }
            is LexiconFfiException.ConfigException -> {
                buf.putInt(2)
                Unit
            }
            is LexiconFfiException.ModelNotFound -> {
                buf.putInt(3)
                Unit
            }
            is LexiconFfiException.ModelLoadFailed -> {
                buf.putInt(4)
                Unit
            }
            is LexiconFfiException.TranscriptionFailed -> {
                buf.putInt(5)
                Unit
            }
            is LexiconFfiException.SynthesisFailed -> {
                buf.putInt(6)
                Unit
            }
            is LexiconFfiException.InvalidInput -> {
                buf.putInt(7)
                Unit
            }
            is LexiconFfiException.IoException -> {
                buf.putInt(8)
                Unit
            }
            is LexiconFfiException.DatabaseException -> {
                buf.putInt(9)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}





